const weightTrackerLeadsDashboard = async (req, res, next) => {
  try {
    const { mentor_id, search, page, limit, filter = "today" } = req.body;
    if (!mentor_id) {
      return next(new ErrorHandler("Mentor ID is required", 400));
    }
    const filterMap = new Map([
      [
        "today",
        [
          {
            field: "DATE(wrl.added_date)",
            operator: "=",
            value: "CURDATE()",
            raw: true,
          },
        ],
      ],
      [
        "yesterday",
        [
          {
            field: "DATE(wrl.added_date)",
            operator: "=",
            value: "CURDATE() - INTERVAL 1 DAY",
            raw: true,
          },
        ],
      ],
      [
        "mtd",
        [
          {
            field: "DATE(wrl.added_date)",
            operator: "BETWEEN",
            value: [
              `${moment().startOf("month").format("YYYY-MM-DD")}`,
              `${moment().endOf("day").format("YYYY-MM-DD")}`,
            ],
          },
        ],
      ],
    ]);
    const baseConditions = [
      {
        field: "cd.counsellor_assigned",
        operator: "=",
        value: parseInt(mentor_id),
      },
      {
        field: "cd.user_type",
        operator: "=",
        value: "0",
      },
      {
        field: "wrl.weight_acknowledge",
        operator: "=",
        value: "0",
      },
    ];
    const conditions = [...baseConditions];

    conditions.push(...filterMap.get(filter));
    const { results: data, totalCount } = await readRecordNewForLead({
      withQueries: [
        ...withMap.get("latest_health"),
        {
          name: "sl_weight_record",
          query: `SELECT *
  FROM (
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY added_date DESC) AS rn
    FROM weight_records_lead
    WHERE added_date < CURDATE()
  ) AS ranked_weights
  WHERE rn = 1`,
        },
      ],
      selectFields: [
        ...getCommonSelectFields(),
        "wrl.weight",
        "wrl.added_date",
        "slwr.weight as previous_weight",
        "slwr.weight - wrl.weight as weight_difference",
        "wrl.id as weight_record_id",
      ],
      table: `${tables.weightRecordsLead} wrl`,
      joins: [
        {
          type: "LEFT",
          table: `${tables.userDetails} cd`,
          on: "wrl.user_id = cd.user_id",
        },
        {
          type: "LEFT",
          table: `sl_weight_record slwr`,
          on: "slwr.user_id = wrl.user_id ",
        },
        ...getCommonJoins(),
      ],
      conditions,
      orderBy: ["wrl.added_date DESC"],
      groupBy: ["cd.user_id"],
      search: {
        searchQuery: search,
        searchFields: [
          "CONCAT(cd.first_name, ' ', cd.last_name)",
          "cd.email_id",
          "cd.phone",
        ],
      },
      pagination: {
        page,
        limit,
      },
      countTotal: true,
    });
    const finalData = data.map((item, index) => {
      const mappedData = mapLeadDataNew({
        details: item,
        extraMappings: {
          weight_details: {
            id: item.weight_record_id || null,
            weight: item.weight || "N/A",
            added_date: item.added_date
              ? moment(item.added_date).format("YYYY-MM-DD")
              : "N/A",
            weight_difference: item.weight_difference,
          },
        },
      });
      return mappedData;
    });
    const countsUnion = [];
    for (const [key, filterCondition] of filterMap.entries()) {
      countsUnion.push({
        table: `${tables.weightRecordsLead} wrl`,
        selectField: [
          "COUNT(DISTINCT wrl.user_id) as count",
          `'${key}' as type`,
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.userDetails} cd`,
            on: "cd.user_id = wrl.user_id",
          },
        ],
        condition: [...baseConditions, ...filterCondition],
      });
    }
    const countData = await readRecordUnion(countsUnion);
    const counts = {};
    countData.forEach((item) => {
      counts[item.type] = parseInt(item.count);
    });
    const apiResponse = new ApiResponse({
      statusCode: 200,
      message: "Weight Tracker Leads Dashboard data fetched successfully",
      data: finalData,
      totalCount,
      meta_data: {
        counts,
      },
    });
    return res.status(200).json(apiResponse);
  } catch (error) {
    console.log("Error in weightTrackerLeadsDashboard controller:", error);
    return next(new ErrorHandler("Internal server error", 500));
  }
};

