const additionalQuestionsLeadsDashboard = async (req, res, next) => {
  try {
    const { mentor_id, search, page, limit, filter = "today" } = req.body;
    if (!mentor_id) {
      return next(new ErrorHandler("Mentor ID is required", 400));
    }
    const baseConditions = [
      {
        field: "cd.counsellor_assigned",
        operator: "=",
        value: parseInt(mentor_id),
      },
      { field: "aq.is_ack", operator: "=", value: 0 },
    ];
    const filterMap = new Map([
      [
        "today",
        [
          {
            field: "DATE(aq.added_date)",
            operator: "=",
            value: "CURDATE()",
            raw: true,
          },
        ],
      ],
      [
        "yesterday",
        [
          {
            field: "DATE(aq.added_date)",
            operator: "=",
            value: "CURDATE() - INTERVAL 1 DAY",
            raw: true,
          },
        ],
      ],
      [
        "day_before_yesterday",
        [
          {
            field: "DATE(aq.added_date)",
            operator: "=",
            value: "CURDATE() - INTERVAL 2 DAY",
            raw: true,
          },
        ],
      ],
      [
        "mtd",
        [
          {
            field: "DATE(aq.added_date)",
            operator: "BETWEEN",
            value: [
              `${moment().startOf("month").format("YYYY-MM-DD")}`,
              `${moment().endOf("day").format("YYYY-MM-DD")}`,
            ],
          },
        ],
      ],
    ]);
    const conditions = [...baseConditions, ...filterMap.get(filter)];
    const { results: data, totalCount } = await readRecordNewForLead({
      withQueries: [...withMap.get("latest_health")],
      selectFields: [
        ...getCommonSelectFields(),
        "aq.result",
        "aq.added_date",
        "aq.id",
      ],
      table: `${tables.additionalQuestions} aq`,
      joins: [
        {
          type: "LEFT",
          table: `${tables.userDetails} cd`,
          on: "aq.user_id = cd.user_id",
        },
        ...getCommonJoins(),
      ],
      conditions,
      orderBy: ["aq.added_date DESC"],
      groupBy: ["cd.user_id"],
      search: {
        searchQuery: search,
        searchFields: [
          "CONCAT(cd.first_name, ' ', cd.last_name)",
          "cd.email_id",
          "cd.phone",
        ],
      },
      pagination: {
        page,
        limit,
      },
      countTotal: true,
    });
    const finalData = data.map((item, index) => {
      const questions = safeJSONParse(item.result, {});
      console.log(questions, 2052);
      let questionsFormatted = {};
      console.log(questionsFormatted, 1837, item.user_id);
      for (const question of questions) {
        const valueFormatted = safeJSONParse(question.answer) || {};
        console.log(valueFormatted, 2057);
        const values = Array.isArray(valueFormatted.values)
          ? valueFormatted.values
          : [];
        const anyOther = Array.isArray(valueFormatted.anyOtherValue)
          ? valueFormatted.anyOtherValue
          : [];

        questionsFormatted[question.question] = [...values, ...anyOther].join(
          ", ",
        );
        if (values.length === 0 && !Array.isArray(valueFormatted.values)) {
          questionsFormatted[question.question] = question.answer;
        }
      }

      const mappedData = mapLeadDataNew({
        details: item,
        extraMappings: {
          additional_questions: {
            id: item.id || null,
            question: questionsFormatted || "N/A",
            added_date: item.added_date
              ? moment(item.added_date).format("YYYY-MM-DD")
              : "N/A",
          },
        },
      });
      return mappedData;
    });
    const countsUnion = [];
    for (const [key, filterCondition] of filterMap.entries()) {
      countsUnion.push({
        table: `${tables.additionalQuestions} aq`,
        selectField: [
          "COUNT(DISTINCT aq.user_id) as count",
          `'${key}' as type`,
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.userDetails} cd`,
            on: "cd.user_id = aq.user_id",
          },
        ],
        condition: [...baseConditions, ...filterCondition],
      });
    }
    const countData = await readRecordUnion(countsUnion);
    const counts = {};
    countData.forEach((item) => {
      counts[item.type] = parseInt(item.count);
    });
    const apiResponse = new ApiResponse({
      statusCode: 200,
      message: "Additional Questions Leads Dashboard data fetched successfully",
      data: finalData,
      totalCount,
      meta_data: {
        counts,
      },
    });
    return res.status(200).json(apiResponse);
  } catch (error) {
    console.log(
      "Error in additionalQuestionsLeadsDashboard controller:",
      error,
    );
    return next(new ErrorHandler("Internal server error", 500));
  }
};

const crossCallsLeadsDashboard = async (req, res, next) => {
  try {
    const { mentor_id, search, page, limit, filter = "today" } = req.body;
    // if (!mentor_id) {
    //   return next(new ErrorHandler("Mentor ID is required", 400));
    // }

    const conditions = [
      mentor_id
        ? {
            field: "cu.added_by",
            operator: "=",
            value: parseInt(mentor_id),
          }
        : { field: "cu.added_by", operator: "NOT IN", value: [0, 10, 196] },
      { field: "cu.call_type", operator: "=", value: "50" },
      { field: "cu.call_status", operator: "=", value: 0 },
    ];

    const filterMap = new Map([
      [
        "today",
        [
          {
            field: "DATE(cu.schedule_date)",
            operator: "=",
            value: moment().format("YYYY-MM-DD"),
          },
        ],
      ],
      [
        "tomorrow",
        [
          {
            field: "DATE(cu.schedule_date)",
            operator: "=",
            value: moment().add(1, "day").format("YYYY-MM-DD"),
          },
        ],
      ],
      [
        "missed",
        [
          {
            field: "DATE(cu.schedule_date)",
            operator: "<",
            value: "CURDATE()",
            raw: true,
          },
        ],
      ],
      [
        "future",
        [
          {
            field: "DATE(cu.schedule_date)",
            operator: ">",
            value: "CURDATE()",
            raw: true,
          },
        ],
      ],
    ]);

    conditions.push(...filterMap.get(filter));

    const { results: data, totalCount } = await readRecordNewForLead({
      withQueries: [...withMap.get("latest_health")],
      selectFields: [
        ...getCommonSelectFields(),
        "cu.call_id",
        "cu.call_type",
        "cu.call_status",
        `GROUP_CONCAT(
          DISTINCT basm.appointment_slots
          ORDER BY STR_TO_DATE(basm.appointment_slots, '%h:%i %p') SEPARATOR ', '
        ) AS appointment_slots`,
        "cu.slot_id",
        `(SELECT COUNT(*) FROM call_updates cu WHERE cu.user_id = cd.user_id AND DATE(cu.schedule_date) < CURDATE()) AS call_attempts`,
      ],
      table: `${tables.callUpdates} cu`,
      joins: [
        {
          type: "LEFT",
          table: `${tables.userDetails} cd`,
          on: "cu.user_id = cd.user_id",
        },
        ...getCommonJoins(),
        {
          type: "INNER",
          table: `${tables.numbers} n`,
          on: "n.n < 1 + LENGTH(cu.slot_id) - LENGTH(REPLACE(cu.slot_id, ',', ''))",
        },
        {
          type: "LEFT",
          table: `${tables.slots} basm`,
          on: `basm.id = CAST(
            TRIM(
              SUBSTRING_INDEX(SUBSTRING_INDEX(cu.slot_id, ',', n.n + 1), ',', -1)
            ) AS UNSIGNED
          )`,
        },
      ],
      conditions,
      orderBy: ["CAST(SUBSTRING_INDEX(cu.slot_id, ',', 1) AS UNSIGNED)"],
      groupBy: ["cu.call_id", "cu.user_id"],
      search: {
        searchQuery: search,
        searchFields: [
          "CONCAT(cd.first_name, ' ', cd.last_name)",
          "cd.email_id",
          "cd.phone",
        ],
      },
      pagination: {
        page,
        limit,
      },
      countTotal: true,
    });

    const finalData = data.map((item) => {
      const call_status = item.call_status;
      return mapLeadDataNew({
        details: item,
        extraMappings: {
          call_details: {
            call_id: item.call_id || null,
            call_type: item.call_type || "N/A",
            call_status:
              call_status === 0
                ? "Pending"
                : call_status === 1
                  ? "Done"
                  : call_status === 2
                    ? "Cancelled"
                    : call_status === 3
                      ? "Rescheduled"
                      : "Unanswered",
            appointment_slots: item.appointment_slots || "N/A",
            call_attempts: item.call_attempts || 0,
            call_assigned_by: item.counsellor_assigned || "N/A",
          },
        },
      });
    });

    // Count data for each filter
    const countsUnion = [];
    const baseConditions = conditions.filter(
      (cond) => !cond.field?.startsWith("DATE(cu.schedule_date)"),
    );

    for (const [key, filterCondition] of filterMap.entries()) {
      countsUnion.push({
        table: `${tables.callUpdates} cu`,
        selectField: [
          "COUNT(DISTINCT cu.call_id) AS count",
          `'${key}' as type`,
        ],
        condition: [...baseConditions, ...filterCondition],
        join: [
          {
            type: "INNER",
            table: `${tables.userDetails} cd`,
            on: "cd.user_id = cu.user_id",
          },
        ],
      });
    }

    const countData = await readRecordUnion(countsUnion);
    const counts = {};
    countData.forEach((item) => {
      counts[item.type] = parseInt(item.count);
    });

    const apiResponse = new ApiResponse({
      statusCode: 200,
      message: "Cross call Leads Dashboard data fetched successfully",
      data: finalData,
      totalCount,
      meta_data: {
        counts,
      },
    });

    return res.status(200).json(apiResponse);
  } catch (error) {
    console.log("Error in crossCallsLeadsDashboard controller:", error);
    return next(new ErrorHandler("Internal server error", 500));
  }
};

