const mtdSalesRisks = async (req, res, next) => {
  try {
    const { mentor_id } = req.query;

    const data = await readRecordUnion([
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'HOT_followups_pending' as type",
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.leadFollowUpLogs} lfl`,
            on: `cd.user_id = lfl.user_id AND lfl.follow_up_date BETWEEN '${moment()
              .startOf("month")
              .format("YYYY-MM-DD")}' AND '${moment()
              .endOf("day")
              .format("YYYY-MM-DD")}'`,
          },
        ],
        condition: [
          {
            field: "lfl.follow_up_id",
            operator: "IS",
            value: "NULL",
            raw: true,
          },
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          { field: "cd.sales_status", operator: "=", value: 2 },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'unacknowledged_milestones' as type",
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.userMilestones} um`,
            on: "cd.user_id = um.user_id AND um.added_by = 'User'",
          },
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          { field: "um.is_ack", operator: "=", value: 0 },
          {
            field: "um.added_date",
            operator: "BETWEEN",
            value: [
              moment().startOf("month").format("YYYY-MM-DD"),
              moment().endOf("day").format("YYYY-MM-DD"),
            ],
          },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'to_pay_OD' as type",
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          { field: "cd.sub_sales_status", operator: "=", value: "To Pay" },
          {
            field: "cd.payment_date",
            operator: "<",
            value: "CURDATE()",
            raw: true,
          },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'pay_later_OD' as type",
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          { field: "cd.sub_sales_status", operator: "=", value: "Pay Later" },
          {
            field: "cd.payment_date",
            operator: "<",
            value: "CURDATE()",
            raw: true,
          },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'wallet_expiring_tomorrow' as type",
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          {
            field: "cd.wallet_cycle_end_date",
            operator: "=",
            value: "CURDATE() + INTERVAL 1 DAY",
            raw: true,
          },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'extra_discount_expiring_tomorrow' as type",
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.leadsActivatedFeatures} laf`,
            on: "cd.user_id = laf.user_id",
          },
          {
            type: "LEFT",
            table: `${tables.prizeDetails} pd`,
            on: "cd.user_id = pd.user_id",
          },
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          {
            orConditions: [
              {
                field: "cd.wallet_cycle_end_date",
                operator: "=",
                value: "CURDATE() + INTERVAL 1 DAY",
                raw: true,
              },
              {
                field: "JSON_UNQUOTE(JSON_EXTRACT(laf.coupon, '$.end_date'))",
                operator: "=",
                value: "CURDATE() + INTERVAL 1 DAY",
                raw: true,
              },
              {
                field: "pd.added_date",
                operator: "=",
                value: "CURDATE() - INTERVAL 1 DAY",
                raw: true,
              },
            ],
          },
        ],
      },
      {
        table: `${tables.userDetails} cd`,
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'HOT_lead_with_negative_feedback' as type",
        ],
        join: [
          {
            type: "LEFT",
            table: `${tables.leadFeedback} lfb`,
            on: "cd.user_id = lfb.user_id AND lfb.type = 'Consultation'",
          },
        ],
        condition: [
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          { field: "cd.user_type", operator: "=", value: "0" },
          { field: "cd.sales_status", operator: "=", value: 2 },
          {
            field: "LCASE(JSON_UNQUOTE(JSON_EXTRACT(lfb.feedback,'$.rating')))",
            operator: "=",
            value: "sad",
          },
          {
            field: "DATE(lfb.added_date)",
            operator: "BETWEEN",
            value: [
              `${moment().startOf("month").format("YYYY-MM-DD")}`,
              `${moment().endOf("day").format("YYYY-MM-DD")}`,
            ],
          },
        ],
      },
      {
        selectField: [
          "COUNT(DISTINCT cd.user_id) AS count",
          "'unconverted_leads_with_GO_pro' as type",
        ],
        table: `${tables.subOrderPrograms} sop`,
        join: [
          {
            type: "LEFT",
            table: `${tables.userDetails} cd`,
            on: "sop.user_id = cd.user_id",
          },
        ],
        condition: [
          { field: "sop.type", operator: "=", value: 1 },
          mentor_id
            ? {
                field: "cd.counsellor_assigned",
                operator: "=",
                value: parseInt(mentor_id),
              }
            : {
                field: "cd.counsellor_assigned",
                operator: "NOT IN",
                value: [0, 10, 196],
              },
          {
            field: "cd.user_type",
            operator: "=",
            value: "0",
          },
          {
            field: "sop.expiry_date",
            operator: "BETWEEN",
            value: [
              `${moment().startOf("month").format("YYYY-MM-DD")}`,
              `${moment().endOf("day").format("YYYY-MM-DD")}`,
            ],
          },
        ],
      },
    ]);
    const finalCount = data.reduce((acc, item) => {
      acc[item.type] = parseInt(item.count);
      return acc;
    }, {});

    const freeCourseExpired = new Map();

    const { results: leadsWithFreeCourse } = await readRecord({
      table: `${tables.userDetails} cd`,
      selectFields: ["laf.guides", "laf.user_id"],
      joins: [
        {
          type: "LEFT",
          table: `${tables.leadsActivatedFeatures} laf`,
          on: "laf.user_id = cd.user_id",
        },
        {
          type: "LEFT",
          table: `${tables.subOrderPrograms} sop`,
          on: "sop.user_id = cd.user_id AND sop.type = 1",
        },
      ],
      conditions: [
        mentor_id
          ? {
              field: "cd.counsellor_assigned",
              operator: "=",
              value: parseInt(mentor_id),
            }
          : {
              field: "cd.counsellor_assigned",
              operator: "NOT IN",
              value: [0, 10, 196],
            },
        { field: "cd.user_type", operator: "=", value: "0" },
        { field: "sop.sub_order_id", operator: "IS", value: "NULL", raw: true },
        { field: "JSON_LENGTH(laf.guides)", operator: ">", value: 0 },
      ],
    });

    leadsWithFreeCourse.forEach((item) => {
      let guides = [];
      try {
        guides = JSON.parse(item.guides || "[]");
      } catch (err) {
        guides = [];
      }

      if (guides.length === 0) return;

      // Check if all guides are expired
      const allExpired = guides.every((guide) => {
        return (
          guide?.guide_end_date &&
          moment(guide.guide_end_date, "YYYY-MM-DD", true).isBefore(
            moment(),
            "day",
          )
        );
      });

      if (!allExpired) return;

      // Check if at least one expired in the current month
      const atLeastOneExpiredThisMonth = guides.some((guide) => {
        if (!guide?.guide_end_date) return false;
        const endDate = moment(guide.guide_end_date, "YYYY-MM-DD", true);
        return (
          endDate.isBefore(moment(), "day") &&
          endDate.month() === moment().month() &&
          endDate.year() === moment().year()
        );
      });

      if (atLeastOneExpiredThisMonth) {
        freeCourseExpired.set(item.user_id, guides.length);
      }
    });

    finalCount["unconverted_leads_with_free_course"] = freeCourseExpired.size;

    const apiResponse = new ApiResponse({
      statusCode: 200,
      message: "MTD Sales Risks data fetched successfully",
      data: finalCount,
    });
    return res.status(200).json(apiResponse);
  } catch (error) {
    console.log("Error in mtdSalesRisks controller:", error);
    return next(new ErrorHandler("Internal server error", 500));
  }
};

