const performanceTrendChart = async (req, res, next) => {
  try {
    const {
      mentor_id,
      start_date = moment()
        .subtract(6, "months")
        .startOf("month")
        .format("YYYY-MM-DD"),
      end_date = moment().endOf("month").format("YYYY-MM-DD"),
    } = req.query;
    if (!mentor_id) {
      return next(new ErrorHandler("Mentor ID is required", 400));
    }
    async function monthWisePerformanceData(start_date, end_date) {
      const { results: assignedData } = await readRecord({
        selectFields: ["COUNT(DISTINCT cd.user_id) AS count"],
        table: `${tables.userDetails} cd`,
        joins: [
          {
            type: "INNER",
            table: `${tables.leadAssignedLog} lal`,
            on: `cd.user_id = lal.user_id AND cd.counsellor_assigned = lal.counsellor_id AND DATE(cd.added_date) BETWEEN '${start_date}' AND '${end_date}'`,
          },
        ],
        conditions: [
          { field: "cd.phone_code", operator: "!=", value: "" },
          {
            field: "cd.counsellor_assigned",
            operator: "=",
            value: mentor_id,
          },
        ],
      });
      const { results: consultationData } = await readRecord({
        selectFields: ["COUNT(DISTINCT csl.user_id) AS count"],
        table: `${tables.consultationLogs} csl`,
        conditions: [
          { field: "csl.consultation_by", operator: "=", value: mentor_id },
          {
            field: "DATE(csl.added_date)",
            operator: "BETWEEN",
            value: [start_date, end_date],
          },
        ],
      });
      const { results: salesData } = await readRecord({
        selectFields: ["COUNT(DISTINCT sop.sub_order_id) AS count"],
        table: `${tables.orderDetails} od`,
        joins: [
          {
            type: "LEFT",
            table: `${tables.subOrderPrograms} sop`,
            on: "od.order_id = sop.order_id",
          },
        ],
        conditions: [
          { field: "od.sale_by", operator: "=", value: mentor_id },
          { field: "od.order_type", operator: "=", value: "New" },
          {
            field: "DATE(od.order_date)",
            operator: "BETWEEN",
            value: [start_date, end_date],
          },
        ],
      });
      const leadsAssigned = assignedData[0]?.count || 0;
      const consultations = consultationData[0]?.count || 0;
      const sales = salesData[0]?.count || 0;
      return {
        leads_assigned: leadsAssigned,
        consultations: consultations,
        sales: sales,
        "l:c": leadsAssigned
          ? ((consultations / leadsAssigned) * 100).toFixed(2)
          : "0.00",
        "c:s": consultations
          ? ((sales / consultations) * 100).toFixed(2)
          : "0.00",
        "l:s": leadsAssigned
          ? ((sales / leadsAssigned) * 100).toFixed(2)
          : "0.00",
        month: moment(start_date).format("MMM YYYY"),
      };
    }
    let data = [];
    console.log(start_date, end_date, 7597);
    for (
      let m = moment(start_date).clone();
      m.isSameOrBefore(end_date, "month");
      m.add(1, "month")
    ) {
      const monthStart = m.clone().startOf("month").format("YYYY-MM-DD");
      const monthEnd = m.clone().endOf("month").format("YYYY-MM-DD");

      const monthData = await monthWisePerformanceData(monthStart, monthEnd);
      data.push(monthData);
    }

    const apiResponse = new ApiResponse({
      statusCode: 200,
      message: "Performance trend chart data fetched successfully",
      data: data,
    });
    return res.status(200).json(apiResponse);
  } catch (error) {
    console.log("Error in performanceTrendChart controller:", error);
    return next(new ErrorHandler("Internal server error", 500));
  }
};

